import React, { useState, useEffect, useRef } from 'react';
import MeshSphere from '../components/MeshSphere';

const PHASES = [
  { name:'Andas in',  seconds:4, label:'Djupt in genom näsan', speed:0.05,  distort:0.2 },
  { name:'Håll',      seconds:7, label:'Håll andan stilla',    speed:0.008, distort:0.08 },
  { name:'Andas ut',  seconds:8, label:'Långsamt ut',          speed:0.02,  distort:1.8 },
];
const TOTAL = 4;

export default function Breathing({ setPage }) {
  const [running, setRunning] = useState(false);
  const [done,    setDone]    = useState(false);
  const [phase,   setPhase]   = useState(0);
  const [count,   setCount]   = useState(0);
  const [cycle,   setCycle]   = useState(0);
  const [orbSize, setOrbSize] = useState(260);
  const timer = useRef(null);

  const runPhase = (pi, ci) => {
    if (ci >= TOTAL) { setRunning(false); setDone(true); return; }
    setPhase(pi); setCycle(ci); setCount(PHASES[pi].seconds);
    // Animate orb size
    if (pi === 0) setOrbSize(320);       // inhale — grows
    else if (pi === 1) setOrbSize(320);  // hold — stays big
    else setOrbSize(200);                // exhale — shrinks

    let c = PHASES[pi].seconds;
    timer.current = setInterval(() => {
      c--; setCount(c);
      if (c <= 0) {
        clearInterval(timer.current);
        const np = (pi+1) % PHASES.length;
        setTimeout(() => runPhase(np, np===0 ? ci+1 : ci), 300);
      }
    }, 1000);
  };

  const start = () => { setRunning(true); setDone(false); setOrbSize(260); runPhase(0,0); };
  useEffect(() => () => clearInterval(timer.current), []);

  const cur = PHASES[phase];

  if (done) return (
    <div style={{ minHeight:'100vh', background:'#0c0c0e', paddingTop:56, paddingBottom:80, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', padding:'80px 20px', position:'relative' }}>
      <div style={{ position:'absolute', inset:0, backgroundImage:'linear-gradient(rgba(255,255,255,0.02) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.02) 1px, transparent 1px)', backgroundSize:'48px 48px', pointerEvents:'none' }} />
      <div style={{ position:'relative', zIndex:1, textAlign:'center' }}>
        <MeshSphere size={240} speed={0.6} distort={0.15} />
        <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.24em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', marginTop:24, marginBottom:10 }}>Komplett · {TOTAL} omgångar</div>
        <h2 style={{ fontSize:40, fontWeight:900, letterSpacing:'-0.05em', textTransform:'uppercase', color:'#f2f0eb', marginBottom:10 }}>Färdig</h2>
        <p style={{ fontSize:13, color:'rgba(242,240,235,0.4)', marginBottom:36, fontWeight:300 }}>Ditt nervsystem har lugnat ner sig.</p>
        <div style={{ display:'flex', gap:8, justifyContent:'center' }}>
          <button onClick={()=>setPage('checkin')} style={{ padding:'12px 20px', border:'none', borderRadius:4, background:'#f2f0eb', color:'#0c0c0e', fontSize:11, fontFamily:'DM Mono,monospace', letterSpacing:'0.12em', textTransform:'uppercase', fontWeight:700 }}>Check-in →</button>
          <button onClick={()=>{setDone(false);setRunning(false);setOrbSize(260);}} style={{ padding:'12px 20px', border:'1px solid rgba(255,255,255,0.1)', borderRadius:4, color:'rgba(242,240,235,0.45)', fontSize:11, fontFamily:'DM Mono,monospace', letterSpacing:'0.12em', textTransform:'uppercase' }}>Igen</button>
        </div>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight:'100vh', background:'#0c0c0e', paddingTop:56, paddingBottom:80, position:'relative', display:'flex', flexDirection:'column' }}>
      <div style={{ position:'absolute', inset:0, backgroundImage:'linear-gradient(rgba(255,255,255,0.02) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.02) 1px, transparent 1px)', backgroundSize:'48px 48px', pointerEvents:'none' }} />

      <div style={{ flex:1, display:'flex', flexDirection:'column', position:'relative', zIndex:1 }}>

        {/* Top info */}
        <div style={{ padding:'20px 20px 0' }}>
          <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.24em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', marginBottom:6 }}>4 – 7 – 8 teknik</div>

          {/* Phase indicators */}
          <div style={{ display:'flex', gap:16 }}>
            {PHASES.map((p,i) => (
              <div key={i}>
                <span style={{ fontSize:20, fontWeight:900, letterSpacing:'-0.04em', color: running&&phase===i ? '#f2f0eb' : 'rgba(242,240,235,0.18)', transition:'color .4s' }}>{p.seconds}</span>
                <div style={{ fontFamily:'DM Mono,monospace', fontSize:8, letterSpacing:'0.1em', textTransform:'uppercase', color: running&&phase===i ? 'rgba(242,240,235,0.45)' : 'rgba(242,240,235,0.15)', transition:'color .4s', marginTop:1 }}>{p.name}</div>
              </div>
            ))}
          </div>
        </div>

        {/* Mesh sphere — THE breathing indicator */}
        <div style={{ flex:1, display:'flex', alignItems:'center', justifyContent:'center', padding:'20px', position:'relative' }}>
          <div style={{ transition:`transform ${running ? (phase===0 ? `${PHASES[0].seconds * 0.85}s` : phase===1 ? '0.5s' : `${PHASES[2].seconds * 0.85}s`) : '1s'} ${phase===0 ? 'cubic-bezier(0.4,0,0.2,1)' : phase===2 ? 'cubic-bezier(0.4,0,0.6,1)' : 'ease'}`, transform: running ? (phase===0||phase===1 ? 'scale(1.2)' : 'scale(0.82)') : 'scale(1)', position:'relative' }}>
            <MeshSphere
              size={280}
              speed={running ? cur.speed : 0.3}
              distort={running ? cur.distort : 0.5}
              color='#f2f0eb'
            />

            {/* Count overlay in centre of sphere */}
            {running && (
              <div style={{ position:'absolute', inset:0, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', pointerEvents:'none' }}>
                <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(242,240,235,0.4)', marginBottom:4 }}>{cur.name}</div>
                <div style={{ fontSize:60, fontWeight:900, color:'rgba(242,240,235,0.9)', lineHeight:1, letterSpacing:'-0.05em' }}>{count}</div>
                <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(242,240,235,0.28)', marginTop:6 }}>{cycle+1} / {TOTAL}</div>
              </div>
            )}
          </div>
        </div>

        {/* Bottom section */}
        <div style={{ padding:'0 20px 20px' }}>
          {running ? (
            <div style={{ border:'1px solid rgba(255,255,255,0.07)', borderRadius:4, padding:'14px 16px', background:'rgba(255,255,255,0.025)', textAlign:'center' }}>
              <p style={{ fontFamily:'DM Mono,monospace', fontSize:10, letterSpacing:'0.14em', textTransform:'uppercase', color:'rgba(242,240,235,0.45)' }}>{cur.label}</p>
            </div>
          ) : (
            <div>
              <h1 style={{ fontSize:'clamp(32px,8vw,52px)', fontWeight:900, letterSpacing:'-0.05em', lineHeight:0.88, color:'#f2f0eb', textTransform:'uppercase', marginBottom:10 }}>
                ANDNING<br/><span style={{ color:'rgba(242,240,235,0.2)' }}>ÖVNING</span>
              </h1>
              <p style={{ fontSize:13, color:'rgba(242,240,235,0.4)', fontWeight:300, lineHeight:1.7, marginBottom:20, maxWidth:300 }}>
                4-7-8 tekniken aktiverar det parasympatiska nervsystemet och reducerar stresshormoner.
              </p>
